22	impl IRBuildable for Block {
23	    fn build(
24	        &self,
25	        program: &mut Program,
26	        my_ir_generator_info: &mut MyIRGeneratorInfo,
27	    ) -> Result<IRBuildResult, String> {
28	        let Block::Default(stmts) = self;
29	        let mut block_result = IRBuildResult::OK;
30	        for stmt in stmts {
31	            let result = stmt.build(program, my_ir_generator_info)?;
32	            // Ignore everything after the return statement.
33	            if let IRBuildResult::EARLYSTOPPING = result {
34	                block_result = result;
35	                break;
36	            }
37	        }
38	        my_ir_generator_info.symbol_tables.delete_new_table();
39	        Ok(block_result)
40	    }
41	}
