89	        match self {
90	            InitVal::Exp(exp) => match exp.build(program, my_ir_generator_info)? {
91	                IRExpBuildResult::Const(int) => Ok(IRInitValBuildResult::Const(int)),
92	                IRExpBuildResult::Value(value) => {
93	                    if is_global {
94	                        Err(format!(
95	                            "Non-constant expression '{:?}' in global variable initval: {:?}",
96	                            exp, self
97	                        ))
98	                    } else {
99	                        Ok(IRInitValBuildResult::Var(value))
100	                    }
101	                }
102	            },
103	            InitVal::Aggregate(childs) => {
104	                let (value, _) =
105	                    build_new_aggregate(shape, childs, is_global, program, my_ir_generator_info)?;
106	                Ok(IRInitValBuildResult::Aggregate(value))
107	            }
108	        }
109	    }
