51	impl MyBBValueTable<'_> {
52	    fn new<'a>(program: &'a Program, fd: &'a FunctionData) -> MyBBValueTable<'a> {
53	        MyBBValueTable {
54	            program,
55	            fd,
56	            curr_time: 0,
57	            register_user: [None; 32],
58	            register_used_time: [0; 32],
59	            local_value_location: HashMap::new(),
60	        }
61	    }
62	
63	    fn __update_user(&mut self, reg: usize, user: Value) {
64	        self.curr_time += 1;
65	        self.register_user[reg] = Some(user);
66	        self.register_used_time[reg] = self.curr_time;
67	    }
68	    fn __free_user(&mut self, reg: usize) {
69	        self.register_user[reg] = None;
70	        self.register_used_time[reg] = 0;
71	    }
72	
73	    fn __is_value_in_register(&self, value: Value) -> Option<usize> {
74	        for i in 0..REGISTER_NAMES.len() {
75	            match self.register_user[i] {
76	                Some(v) => {
77	                    if v == value {
78	                        return Some(i);
79	                    }
80	                }
81	                None => {}
82	            }
83	        }
84	        None
85	    }
86	
87	    fn is_temp_value(&self, value: Value) -> bool {
88	        let value_data = match value.is_global() {
89	            true => self.program.borrow_value(value).clone(),
90	            false => self.fd.dfg().value(value).clone(),
91	        };
92	        match value_data.name() {
93	            Some(name) => name.starts_with("%"),
94	            None => true,
95	        }
96	    }
97	
98	    fn remove_temp_value(&mut self, value: Value) {
99	        // assert!(
100	        //     self.is_temp_value(value),
101	        //     "Can only remove temp values in table!"
102	        // );
103	        if !self.is_temp_value(value) {
104	            return;
105	        }
106	        if let Some(reg) = self.__is_value_in_register(value) {
107	            self.__free_user(reg);
108	        }
109	        self.local_value_location.remove(&value);
110	    }
